UPDATE companies SET description='DAD Manufacturing, Inc. was founded in 1980 in Hiawatha, Iowa, as a family-owned business specializing in stainless steel and aluminum fabrication. The company operates two facilities: its headquarters and stainless steel manufacturing plant in Hiawatha, and a high-volume manufacturing plant in Lisbon, Iowa.

The shop provides laser cutting (tube and flat), bending, rolling, machining, TIG/MIG/spot welding, polishing to 2B cosmetic, #4 sanitary, and #8 sanitary/aesthetic finishes, powder coating, and mechanical, electrical, or manual assembly.

Customers span food manufacturing, pharmaceutical manufacturing, wind power, government, appliance and furniture, transportation, and corn processing. Concrete projects include coating pan tanks for food and pharmaceutical lines, custom aluminum ladders for wind turbines, staircase railings for government buildings, and stainless steel wedge wire baskets for corn handling.

The company developed proprietary welding processes to prevent heat-induced warping and hold tolerances of ±1 mm on weldments up to 10 feet long and 2,300 pounds. Its differentiators include hand polishing to exact RA values, unique fixturing for statistical repeatability, and a reputation built on quality, consistency, and family values over four decades.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Stainless steel fabrication", "Aluminum fabrication", "Laser cutting (tube and flat)", "Bending", "Rolling", "Machining", "TIG welding", "MIG welding", "Spot welding", "Polishing (2B cosmetic, #4 sanitary, #8 sanitary/aesthetic)", "Powder coating", "Mechanical assembly", "Electrical assembly", "Manual assembly", "Custom metal fabrication", "Prototype fabrication", "Pre-production runs", "High-volume production", "Fixturing design", "Shot blasting", "Mirror polishing", "Grain finishing", "Blast finishing"], "industries": ["Food manufacturing", "Pharmaceutical manufacturing", "Wind power", "Government", "Appliance & furniture", "Transportation", "Corn processing", "Industrial product line manufacturing"], "materials": ["Stainless steel", "Aluminum", "Copper"], "equipment": [], "volume": "Prototype to high-volume production", "lead_time": "", "tolerances": "\u00b11 mm on weldments up to 10 feet long and 2,300 pounds", "built_on": [], "facts_used": ["Founded 1980 in Hiawatha, Iowa -> db", "Family-owned company -> / (homepage)", "Two plants: Hiawatha (HQ) and Lisbon (high-volume) -> / (homepage)", "ISO 9001:2015 certified -> / (homepage)", "Capabilities: laser cutting, bending, rolling, machining, TIG/MIG/spot welding, polishing, powder coating, assembly -> / (homepage)", "2.6M parts fabricated, 217K jobs, 99% on-time, 536 customers -> / (homepage)", "Industries: food, pharmaceutical, wind power, government, appliance & furniture, transportation, corn -> / (homepage)", "Tolerances: \u00b11 mm on 10 ft, 2,300 lb weldments -> / (homepage)", "Proprietary welding processes to prevent warping -> / (homepage)", "Hand polishing to 2B, #4, #8 finishes -> / (homepage)", "Unique fixturing technology -> / (homepage)"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "The fabrication and polishing of stainless steel and aluminum has set DAD apart since 1980.", "founded_year": "1980", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='dad-manufacturing-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Based in Painesville, Ohio, DEM Medical (formerly Virtec Medical and Virtec Enterprises) operates as an FDA-registered contract manufacturer of Class I and Class II medical devices. The company maintains ISO 9001:2015 and ISO 13485:2016 certifications across its quality system, which covers design, injection molding, electronics, and assembly under one roof.

DEM Medical provides end-to-end product realization from concept through commercialization. Its in-house capabilities include additive manufacturing and precision machining for rapid prototyping, printed circuit board assembly, custom cabling, tooling design and fabrication, and injection molding. The firm supports programs ranging from early-stage prototypes to medium-volume production runs, with flexible order quantities suited to startups and pilot programs.

The company serves medical device OEMs across diagnostic, monitoring, surgical, and homecare segments. Documented project experience includes homecare dialysis and monitoring systems, heated humidifiers, gastric calibration tubes, surgical tables, suction devices, laparoscopic instruments, catheters, ventilatory devices, and laser therapy equipment. As devices become more connected, DEM also supports wearable and instrument-integrated designs.

DEM Medical emphasizes a vertically integrated, U.S.-based model that consolidates engineering, tooling, molding, and assembly within a single quality system. This approach aims to protect schedule and compliance during design transfer, offering customers one accountable partner rather than a fragmented vendor chain. The company also provides FDA 510(k) documentation support and maintains traceable design history files.', certifications=ARRAY['ISO 9001:2015','ISO 13485:2016','FDA registered (Class I and II)']::text[], profile='{"capabilities": ["Custom cabling and connectors", "Printed circuit board assembly (PCBA)", "Analog and digital communication design", "Tooling design and fabrication", "3D printing and rapid prototyping", "Injection molding", "Additive manufacturing", "Precision machining", "Medical device assembly", "FDA 510(k) documentation support", "Design history file management"], "industries": ["Medical devices (Class I and II)", "Diagnostic equipment", "Monitoring equipment", "Surgical equipment", "Homecare medical devices", "Wearable medical devices"], "materials": [], "equipment": [], "volume": "Prototype to medium-volume", "lead_time": "", "tolerances": "", "built_on": ["Vertically integrated team handles engineering, tooling, molding, and assembly in-house", "U.S.-based model ensures speed, compliance, and transparency", "FDA 510(k) documentation support with traceable design history files", "Flexible order volumes including low-volume production for startups and pilot programs"], "facts_used": ["Headquarters: Painesville, Ohio (db)", "FDA registration for Class I and II devices (homepage)", "ISO 9001:2015 and ISO 13485:2016 certifications (homepage)", "Capabilities: additive manufacturing, precision machining, PCB assembly, injection molding, tooling design, cabling (homepage)", "Industries served: medical devices including homecare dialysis, surgical tables, catheters, etc. (homepage)", "Vertically integrated U.S.-based model (homepage)", "Flexible low-volume production (homepage)"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "DEM Medical is an FDA-registered manufacturer of Class I and Class II medical devices", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='dem-medical-dba-virtec-enterprises' AND approved AND profile IS NULL;
