UPDATE companies SET description='DSI Manufacturing operates from Rogers, Minnesota, where it was founded in 1982. The company is led by President Joe Hines and has grown over four decades into a precision metal fabrication and CNC machining specialist.

The shop runs two facilities totaling more than 80,000 square feet, equipped for sheet metal fabrication — laser cutting, stamping, forming, welding, powder coating, and full assembly — as well as advanced CNC machining including 3-, 4-, and 5-axis milling (HAAS VF3SS and VF4), Swiss turning, surface grinding, and finishing. An in-house powder coating line uses Parker Ionics systems and Rapid Engineering ovens, while a dedicated Rapid Response Cell turns prototypes and short-run jobs around in days.

DSI serves industries ranging from retail fixtures and displays to machinery, electronics, communications, automotive and recreational vehicles, oil and energy, agriculture, fluid handling and filtration, medical, and construction. Its customer base includes global retailers and technology firms that rely on quick-turn lightweight metal and plastic components.

The company emphasizes its DSI Proven Process, which combines collaborative design-for-manufacturability engineering, ISO 9001:2015 certified quality management, and a ''Can-Do'' culture focused on fast-paced execution. In-house finishing, rapid prototyping, and a commitment to on-time delivery are cited as key differentiators.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Sheet metal fabrication", "Laser cutting", "Stamping/Punching", "Forming/Bending", "Welding", "Finishing", "Powder coating", "Full assembly", "CNC milling (3-axis, 4-axis, 5-axis)", "CNC turning/Swiss", "Surface grinding", "CNC machining finishing", "Collaborative design & prototyping", "Design for manufacturability (DFM)", "Rapid prototyping", "Rapid Response Cell (RRC)"], "industries": ["Retail fixtures & displays", "Machinery & equipment", "Electronics & computing", "Communications", "Automotive & recreational vehicles", "Oil & energy", "Agriculture", "Fluid handling/filtration", "Medical", "Construction"], "materials": ["Metal", "Plastics", "Aluminum", "PVC", "Peek", "Teflon", "Delrin", "Carbon-fiber composites"], "equipment": ["HAAS VF3SS", "HAAS VF4", "Parker Ionics powder systems", "Rapid Engineering ovens (6x9x10 feet)", "PEM two-stage washing", "Manual cleaning systems"], "volume": "Prototype to high-volume production runs", "lead_time": "Prototypes in days via Rapid Response Cell", "tolerances": "", "built_on": ["Rapid Response Cell turns prototypes in days, not weeks", "In-house powder coating with Parker Ionics systems and Rapid Engineering ovens", "ISO 9001:2015 certified quality management", "Collaborative design-for-manufacturability (DFM) approach", "Two facilities totaling over 80,000 sq ft of manufacturing space"], "facts_used": ["Founded 1982 -> db, /about-us", "Headquarters Rogers, Minnesota -> db, /about-us", "ISO 9001:2015 certified -> db, /about-us", "Two facilities over 80,000 sq ft -> /about-us", "Sheet metal fabrication capabilities: laser cutting, stamping, forming, welding, powder coating, assembly -> /about-us", "CNC machining: 3/4/5-axis milling (HAAS VF3SS, VF4), Swiss turning, surface grinding -> /about-us", "In-house powder coating with Parker Ionics, Rapid Engineering ovens, PEM washing -> /about-us FAQ", "Rapid Response Cell for prototypes in days -> /, /about-us", "Industries served: retail fixtures, machinery, electronics, communications, automotive, oil & energy, agriculture, fluid handling, medical, construction -> /about-us", "President Joe Hines -> /", "Materials: aluminum, PVC, Peek, Teflon, Delrin, carbon-fiber composites -> /about-us FAQ", "Collaborative design for manufacturability (DFM) -> /about-us", "DSI Proven Process -> /, /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "DSI Manufacturing (DSI) is an ISO 9001: 2015 certified precision Metal Fabrication and CNC Machining manufacturing company.", "founded_year": "1982", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='dsi-manufacturing' AND approved AND profile IS NULL;
UPDATE companies SET description='Daddy''s Workshop of the Carolinas operates from Lancaster, South Carolina, where founder Joshua Pauling runs a one-person woodworking studio alongside his roles as vicar, headmaster, and teacher at All Saints Lutheran Church and All Saints Classical Academy. The workshop began as an extension of Pauling''s personal commitment to handcrafted quality, though a specific founding year is not publicly documented.

The shop produces custom furniture pieces using solid natural wood, focusing on Craftsman and Shaker designs that emphasize traditional joinery and honest construction. Pauling builds each item to order, either from original designs or from customer-supplied images, and also restores vintage woodworking machinery, returning older equipment to working condition. Output remains at a craft scale, with no published figures for facility size, headcount, or annual volume.

The workshop serves individual clients seeking heirloom-quality furniture and collectors or hobbyists needing vintage machinery restoration. While no specific industry sectors are listed, the work aligns with residential furniture, custom woodworking, and antique tool restoration markets.

Pauling positions the business as a counterpoint to mass-produced, particle-board furniture, arguing that handcrafted pieces reconnect people to the physicality of making and the provenance of materials. The emphasis on natural wood, traditional styles, and the restoration of older machines reflects a stated philosophy of valuing human touch and durability over disposable consumption.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture making", "Furniture design", "Vintage machinery restoration", "Woodworking"], "industries": [], "materials": ["Natural wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom furniture design from scratch or from customer images", "Specialization in Craftsman and Shaker furniture styles", "Restoration of vintage woodworking machinery", "Use of natural solid wood rather than particle board"], "facts_used": ["Company name and location -> db", "Owner name Joshua Pauling and his other roles -> /", "Activities: hand-crafted furniture and vintage machinery restoration -> /", "Styles: Craftsman and Shaker -> /", "Design approach: from scratch or from picture -> /", "Philosophy: natural wood, human touch, alternative to particle board -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "I make hand-crafted furniture and refurbish old woodworking machinery.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='daddy-s-workshop-of-the-carolinas' AND approved AND profile IS NULL;
